import sys
from collections import deque
from bisect import bisect_left


def main():
    data = map(int, sys.stdin.buffer.read().split())
    try:
        n = next(data)
        m = next(data)
    except StopIteration:
        return

    edges = []
    minimum_left = [10**10] * (n + 1)
    minimum_right = [10**10] * (n + 1)

    for _ in range(m):
        airport = next(data)
        factory = next(data)
        days = next(data)
        edges.append((days, airport, factory))
        if days < minimum_left[airport]:
            minimum_left[airport] = days
        if days < minimum_right[factory]:
            minimum_right[factory] = days

    lower_bound = max(max(minimum_left[1:]), max(minimum_right[1:]))
    if lower_bound == 10**10:
        print(-1)
        return

    edges.sort()
    values = sorted({edge[0] for edge in edges})
    sys.setrecursionlimit(2 * n + 100)

    def feasible(limit):
        adjacency = [[] for _ in range(n + 1)]
        for days, airport, factory in edges:
            if days > limit:
                break
            adjacency[airport].append(factory)

        left_match = [0] * (n + 1)
        right_match = [0] * (n + 1)
        distance = [0] * (n + 1)
        infinity = n + 1
        matched = 0

        def augment(airport):
            if airport == 0:
                return True

            next_distance = distance[airport] + 1
            for factory in adjacency[airport]:
                other = right_match[factory]
                if distance[other] == next_distance and augment(other):
                    left_match[airport] = factory
                    right_match[factory] = airport
                    return True

            distance[airport] = infinity
            return False

        while True:
            queue = deque()
            distance[0] = infinity

            for airport in range(1, n + 1):
                if left_match[airport] == 0:
                    distance[airport] = 0
                    queue.append(airport)
                else:
                    distance[airport] = infinity

            while queue:
                airport = queue.popleft()
                if distance[airport] >= distance[0]:
                    continue

                next_distance = distance[airport] + 1
                for factory in adjacency[airport]:
                    other = right_match[factory]
                    if distance[other] == infinity:
                        distance[other] = next_distance
                        if other:
                            queue.append(other)

            if distance[0] == infinity:
                return False

            for airport in range(1, n + 1):
                if left_match[airport] == 0 and augment(airport):
                    matched += 1
                    if matched == n:
                        return True

    low = bisect_left(values, lower_bound)
    high = len(values)

    while low < high:
        middle = (low + high) // 2
        if feasible(values[middle]):
            high = middle
        else:
            low = middle + 1

    print(values[low] if low < len(values) else -1)


if __name__ == "__main__":
    main()
